import sys, os, importlib, warnings, traceback, re
warnings.simplefilter('ignore')
repo=os.getcwd(); sys.path.insert(0, repo)
ex=sys.argv[1]
os.chdir(os.path.join(repo,'examples',ex)); sys.path.insert(0, os.getcwd())
try:
    m=importlib.import_module('main')
    app=m.app
    if hasattr(m,'build_sample_db'):
        with app.app_context():
            try: m.build_sample_db()
            except Exception as e: print('  sample db:', type(e).__name__, e)
    app.config['TESTING']=False
    c=app.test_client()
    rules=sorted({r.rule for r in app.url_map.iter_rules() if 'GET' in r.methods and '<' not in r.rule and 'static' not in r.rule and 'export' not in r.rule})
    bad=[]
    for u in rules:
        try:
            r=c.get(u)
            if r.status_code>=500: bad.append((u,r.status_code))
        except Exception as e:
            bad.append((u, f'{type(e).__name__}: {e}'.splitlines()[0][:150]))
    print(f'{ex}: {len(rules)} urls, failures: {bad[:8]}')
except Exception as e:
    print(f'{ex}: STARTUP {type(e).__name__}: {str(e)[:150]}')
EOF
